// Atalhos para montar ingredientes:
// i(id, ml) — quantidade em ml; q = texto livre; opt = opcional; alt = substitutos aceitos; top = completar
const i = (id, ml, extra = {}) => ({id, ml, ...extra});
const t = (id, q, extra = {}) => ({id, q, ...extra});

